{"content":"import unittest

from sgf_parsing import SgfTree, parse


class SgfParsingTests(unittest.TestCase):
    def test_empty_node(self):
        self.assertEqual(parse("(;)"), SgfTree())

    def test_sequence(self):
        expected = SgfTree(
            {"FF": ["4"], "C": ["root"], "SZ": ["19"]},
            [SgfTree({"B": ["aa"]}, [SgfTree({"W": ["ab"]})])],
        )
        self.assertEqual(parse("(;FF[4]C[root]SZ[19];B[aa];W[ab])"), expected)

    def test_variations_attach_to_last_node(self):
        expected = SgfTree(
            {"FF": ["4"]},
            [SgfTree({"B": ["aa"]}, [
                SgfTree({"W": ["ab"]}, [SgfTree({"B": ["ac"]})]),
                SgfTree({"W": ["ee"]}),
            ])],
        )
        self.assertEqual(
            parse("(;FF[4];B[aa](;W[ab](;B[ac]))(;W[ee]))"), expected
        )

    def test_multiple_and_empty_values(self):
        self.assertEqual(
            parse("(;AB[aa][ab][ba]C[])"),
            SgfTree({"AB": ["aa", "ab", "ba"], "C": [""]}),
        )

    def test_text_whitespace(self):
        self.assertEqual(
            parse("(;C[a\tb\vc\fd\n雪])"),
            SgfTree({"C": ["a b c d\n雪"]}),
        )

    def test_escaped_whitespace(self):
        self.assertEqual(
            parse("(;C[a\\\nb\\\tc\\ d])"),
            SgfTree({"C": ["ab c d"]}),
        )

    def test_escapes_are_literal_not_python_sequences(self):
        self.assertEqual(
            parse(r"(;C[\n\t\]\\\[\(\)\;])"),
            SgfTree({"C": ["nt]\\[();"]}),
        )

    def test_delimiters_inside_values(self):
        self.assertEqual(parse("(;C[(;B[aa);])"), SgfTree({"C": ["(;B[aa);"]}))

    def test_required_error_messages(self):
        cases = [
            ("", "tree missing"),
            (";", "tree missing"),
            ("()", "tree with no nodes"),
            ("(FF[4])", "tree with no nodes"),
            ("(;A)", "properties without delimiter"),
            ("(;A[B)", "properties without delimiter"),
            ("(;A[abc" + "\\", "properties without delimiter"),
            ("(;a[b])", "property must be in uppercase"),
            ("(;Ab[b])", "property must be in uppercase"),
        ]
        for text, message in cases:
            with self.subTest(text=text):
                with self.assertRaises(ValueError) as error:
                    parse(text)
                self.assertEqual(str(error.exception), message)

    def test_other_malformed_trees(self):
        for text in [
            "(;", "(;A[b]", "(;))", "(;)(;)", "(;);", "((;))",
            "(;A[b]A[c])", "(;[b])", "(;A[b]])", "(;A1[b])",
            "(;É[b])", "(;A[b](;);)",
        ]:
            with self.subTest(text=text):
                with self.assertRaises(ValueError) as error:
                    parse(text)
                self.assertTrue(str(error.exception))

    def test_long_sequence(self):
        tree = parse("(" + ";" * 2000 + ")")
        count = 1
        while tree.children:
            self.assertEqual(len(tree.children), 1)
            tree = tree.children[0]
            count += 1
        self.assertEqual(count, 2000)


if __name__ == "__main__":
    unittest.main()
